function startDueFor(at, now) {
  const from = Math.max(now.getTime(), at ? new Date(at).getTime() - DUE_SLACK_S * 1000 : 0);
  const q = TICK_S * 1000;
  return new Date(Math.ceil(from / q) * q);
}
